function e(e,t=1,n=`0`){return e==null||Number.isNaN(Number(e))?n:Number(e).toFixed(t).replace(/\.0+$|(\.\d*[1-9])0+$/,`$1`)}function t(t,n=2){return`${e(t,n)} 元`}function n(t,n=1){return`${e(t,n)} 分`}function r(t,n=2){return`${e(t,n)} kg`}function i(e,t=`暂无`){if(!e)return t;let n=new Date(e);return Number.isNaN(n.getTime())?e.replace(`T`,` `):`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,`0`)}-${String(n.getDate()).padStart(2,`0`)} ${String(n.getHours()).padStart(2,`0`)}:${String(n.getMinutes()).padStart(2,`0`)}`}function a(e){return e===1?`男`:e===2?`女`:`-`}function o(e,t=`-`){return e&&(e.dormNo||[e.dormBuilding,e.dormRoom].filter(Boolean).join(`-`))||t}function s(e){return String(e||``).toUpperCase()===`WATER`?`水费`:`电费`}function c(e){let t=String(e||``).toUpperCase();return t===`RECHARGE`?`充值`:t===`REFRESH`?`刷新`:t===`DEDUCT`?`周期扣费`:`消费`}function l(e){let t=String(e||``).toUpperCase();return t===`ALIPAY`?`支付宝`:t===`WECHAT`?`微信`:t===`CASH`?`现金`:t===`SYSTEM`?`系统`:`-`}function u(t,n=``){return t==null?`-`:`1${n} = ${e(t,4)} 元`}export{s as a,c,u as d,o as i,l,t as n,a as o,i as r,e as s,r as t,n as u};